$("logFilter").addEventListener("click", clearSel);
$("chartbox").addEventListener("mousemove", chartMove);
$("chartbox").addEventListener("mouseleave", chartLeave);
$("modeFeed").addEventListener("click", function () { setMode("feed"); });
$("modeLive").addEventListener("click", function () { setMode("live"); });
