  // ---- terminal ---------------------------------------------------------------------
  const reducedMotion = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const term = new Terminal({
    convertEol: true,
    cursorBlink: !reducedMotion,
    scrollback: 5000,
    fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace',
    fontSize: 12,
    theme: {           // hardcoded palette matching grid.html (xterm can't read CSS vars)
      background: "#0a0f0c", foreground: "#cdeedd", cursor: "#3dff7c",
      cursorAccent: "#0a0f0c", selectionBackground: "#1fae5a44",
      black: "#0a0f0c", red: "#ff6f6f", green: "#3dff7c", yellow: "#ffcf6b",
      blue: "#5bd7dd", magenta: "#c792ea", cyan: "#5bd7dd", white: "#cdeedd",
      brightBlack: "#7fa08d", brightWhite: "#ffffff",
    },
  });
